contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address accessControl, uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) public {
        require(accessControl != address(0), "accessControl zero");

        c.initialize(accessControl);

        c.setLimits(maxMultiplier, minMultiplier, rate);

        VaultAdapterStorage storage $ = getVaultAdapterStorage();

        assert(
            $.maxMultiplier == maxMultiplier &&
            $.minMultiplier == minMultiplier &&
            $.rate == rate
        );
    }

    function getVaultAdapterStorage() internal pure returns (VaultAdapterStorage storage $) {
        bytes32 slot = 0x2b1d5d801322d1007f654ac87d8072a5f5ca4203517edc869ef2aa54addad600;
        assembly {
            $.slot := slot
        }
    }

    struct VaultAdapterStorage {
        mapping(address => VaultAdapterStorageSlopeData) slopeData;
        mapping(address => mapping(address => VaultAdapterStorageUtilizationData)) utilizationData;
        uint256 maxMultiplier;
        uint256 minMultiplier;
        uint256 rate;
    }

    struct VaultAdapterStorageSlopeData {
        uint256 kink;
        uint256 slope0;
        uint256 slope1;
    }

    struct VaultAdapterStorageUtilizationData {
        uint256 multiplier;
        uint256 index;
        uint256 lastUpdate;
    }

    receive() external payable {}
}

